CREATE FUNCTION public.document_commit_receipt(p_intake uuid,p_verification jsonb,p_values jsonb,p_path text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.sales_receipt_intakes%ROWTYPE;v public.venues%ROWTYPE;s public.sales_records%ROWTYPE;j uuid;total numeric;paid numeric;k text;BEGIN
IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Independent server verification required';END IF;
SELECT * INTO i FROM public.sales_receipt_intakes WHERE id=p_intake FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Receipt intake missing';END IF;
IF i.status='posted' THEN RETURN jsonb_build_object('status','saved','recordId',i.posted_record_id,'journal','completed');END IF;
IF NOT public.user_has_tenant(i.uploaded_by,i.tenant_id) OR NOT(public.has_role(i.uploaded_by,'admin') OR public.has_role(i.uploaded_by,'manager')) THEN RAISE EXCEPTION 'Receipt permission changed';END IF;
SELECT * INTO v FROM public.venues WHERE tenant_id=i.tenant_id AND name=p_values->>'venue';IF NOT FOUND OR NOT public.user_has_venue(i.uploaded_by,v.id) THEN RAISE EXCEPTION 'Venue unavailable';END IF;
IF p_verification IS NULL OR (p_verification->>'date') IS DISTINCT FROM (p_values->>'date') OR (p_verification->>'venue') IS DISTINCT FROM (p_values->>'venue') THEN RAISE EXCEPTION 'Independent date/venue verification required';END IF;
FOREACH k IN ARRAY ARRAY['subtotal','serviceCharge','discount','totalSales','visa','mastercard','amex','unionPay','jcb','alipay','wechat','payme','cash','deliveroo','foodpanda','keeta','cardTips'] LOOP IF abs(coalesce((p_values->>k)::numeric,0))-abs(coalesce((p_verification->>k)::numeric,0)) NOT BETWEEN -0.01 AND 0.01 THEN RAISE EXCEPTION 'Independent amount verification disagrees: %',k;END IF;END LOOP;
IF p_verification->>'subtotal' IS NULL OR p_verification->>'totalSales' IS NULL THEN RAISE EXCEPTION 'Printed totals missing';END IF;
IF (p_values->>'date')::date>(now() AT TIME ZONE 'Asia/Hong_Kong')::date THEN RAISE EXCEPTION 'Future date cannot post';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('finance-period:'||i.tenant_id::text,0));PERFORM public.finance_assert_open(i.tenant_id,(p_values->>'date')::date);
IF EXISTS(SELECT 1 FROM public.sales_records WHERE tenant_id=i.tenant_id AND venue_id=v.id AND (date=p_values->>'date' OR (nullif(p_values->>'reportNumber','') IS NOT NULL AND report_number=p_values->>'reportNumber'))) THEN RAISE EXCEPTION 'Sales date/report already recorded';END IF;
IF EXISTS(SELECT 1 FROM public.venue_closures WHERE tenant_id=i.tenant_id AND venue_id=v.id AND date=(p_values->>'date')::date) OR EXISTS(SELECT 1 FROM public.venue_closure_rules WHERE tenant_id=i.tenant_id AND venue_id=v.id AND (p_values->>'date')::date>=start_date AND (end_date IS NULL OR (p_values->>'date')::date<=end_date) AND ((weekday IS NOT NULL AND weekday=extract(dow FROM (p_values->>'date')::date)) OR (weekday IS NULL AND end_date IS NOT NULL))) THEN RAISE EXCEPTION 'Venue marked closed';END IF;
total:=(p_values->>'totalSales')::numeric;paid:=0;FOREACH k IN ARRAY ARRAY['visa','mastercard','amex','unionPay','jcb','alipay','wechat','payme','cash','deliveroo','foodpanda','keeta'] LOOP paid:=paid+coalesce((p_values->>k)::numeric,0);END LOOP;
IF total<=0 OR abs(paid-total)>0.01 OR abs((p_values->>'subtotal')::numeric+coalesce((p_values->>'serviceCharge')::numeric,0)-abs(coalesce((p_values->>'discount')::numeric,0))-total)>0.01 THEN RAISE EXCEPTION 'Sales figures do not balance';END IF;
PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',i.uploaded_by,'role','authenticated')::text,true);PERFORM set_config('request.jwt.claim.sub',i.uploaded_by::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);
SELECT * INTO s FROM jsonb_populate_record(NULL::public.sales_records,jsonb_build_object('id',gen_random_uuid(),'tenant_id',i.tenant_id,'date',p_values->>'date','day',to_char((p_values->>'date')::date,'Dy'),'venue',v.name,'venue_id',v.id,'report_number',coalesce(p_values->>'reportNumber',''),'orders',coalesce((p_values->>'orders')::integer,0),'guests',coalesce((p_values->>'guests')::integer,0),'subtotal',(p_values->>'subtotal')::numeric,'service_charge',coalesce((p_values->>'serviceCharge')::numeric,0),'discount',-abs(coalesce((p_values->>'discount')::numeric,0)),'total_sales',total,'card_tips',-abs(coalesce((p_values->>'cardTips')::numeric,0)),'receipt_file_url',p_path,'receipt_file_name',i.source_name,'created_at',now()));
INSERT INTO public.sales_records(id,tenant_id,date,day,venue,venue_id,report_number,orders,guests,subtotal,service_charge,discount,total_sales,visa,mastercard,amex,union_pay,jcb,alipay,wechat,payme,cash,deliveroo,foodpanda,keeta,card_tips,receipt_file_url,receipt_file_name) VALUES(s.id,s.tenant_id,s.date,s.day,s.venue,s.venue_id,s.report_number,s.orders,s.guests,s.subtotal,s.service_charge,s.discount,s.total_sales,coalesce((p_values->>'visa')::numeric,0),coalesce((p_values->>'mastercard')::numeric,0),coalesce((p_values->>'amex')::numeric,0),coalesce((p_values->>'unionPay')::numeric,0),coalesce((p_values->>'jcb')::numeric,0),coalesce((p_values->>'alipay')::numeric,0),coalesce((p_values->>'wechat')::numeric,0),coalesce((p_values->>'payme')::numeric,0),coalesce((p_values->>'cash')::numeric,0),coalesce((p_values->>'deliveroo')::numeric,0),coalesce((p_values->>'foodpanda')::numeric,0),coalesce((p_values->>'keeta')::numeric,0),s.card_tips,s.receipt_file_url,s.receipt_file_name);
PERFORM set_config('bani.accounting.source_type','sales_summary',true);PERFORM set_config('bani.accounting.source_id',s.date||'__'||s.venue,true);PERFORM public._rebuild_journal_from_operations_impl(i.tenant_id,i.uploaded_by,'Bani');SELECT id INTO j FROM public.journal_entries WHERE tenant_id=i.tenant_id AND source_type='sales_summary' AND source_id=s.date||'__'||s.venue AND status='posted';
IF j IS NULL OR EXISTS(SELECT 1 FROM public.journal_lines WHERE entry_id=j AND (account_id IS NULL OR mapping_status='missing')) THEN RAISE EXCEPTION 'Accounts missing; source and journal were not saved';END IF;
UPDATE public.sales_receipt_intakes SET status='posted',posted_record_id=s.id,verification=p_verification,reasons='[]',tentative_values=p_values WHERE id=i.id;
INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(i.tenant_id,i.uploaded_by,'document_posted','sales_records',s.id::text,jsonb_build_object('journal',j,'intake',i.id,'verified','independent_read'));RETURN jsonb_build_object('status','saved','recordId',s.id,'journal','completed');END $$;
REVOKE ALL ON FUNCTION public.document_commit_receipt(uuid,jsonb,jsonb,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.document_commit_receipt(uuid,jsonb,jsonb,text) TO service_role;
DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public._rebuild_journal_from_operations_impl(uuid,uuid,text)'::regprocedure) INTO d;
IF position('document-targeted-sales' IN d)=0 THEN d:=replace(d,'WHERE s.tenant_id = p_tenant_id AND coalesce(current_setting(''bani.accounting.source_type'',true),'''')=''''','WHERE s.tenant_id = p_tenant_id AND (coalesce(current_setting(''bani.accounting.source_type'',true),'''')='''' OR (current_setting(''bani.accounting.source_type'',true)=''sales_summary'' AND s.date||''__''||s.venue=current_setting(''bani.accounting.source_id'',true))) /* document-targeted-sales */');EXECUTE d;END IF;END $patch$;